import{_ as e,o as a,c as t,a2 as r}from"./chunks/framework.DHtetOlu.js";const p=JSON.parse('{"title":"Circuito externo","description":"","frontmatter":{},"headers":[],"relativePath":"guide/circuit.md","filePath":"guide/circuit.md"}'),i={name:"guide/circuit.md"};function s(c,o,n,d,m,l){return a(),t("div",null,[...o[0]||(o[0]=[r('<h1 id="circuito-externo" tabindex="-1">Circuito externo <a class="header-anchor" href="#circuito-externo" aria-label="Permalink to &quot;Circuito externo&quot;">​</a></h1><p>Bobinas de verdade são alimentadas por circuitos: uma fonte de tensão com resistência em série, um transformador com carga, um capacitor descarregando numa bobina. O MagFEM resolve o <strong>campo e o circuito juntos</strong>, num único sistema de equações (acoplamento forte), na análise transitória.</p><h2 id="criar-o-circuito" tabindex="-1">Criar o circuito <a class="header-anchor" href="#criar-o-circuito" aria-label="Permalink to &quot;Criar o circuito&quot;">​</a></h2><ol><li>O <code>+</code> ao lado de <strong>Modelo</strong> cria um <strong>Circuito</strong>, que abre numa aba com o esquemático.</li><li>O esquemático já traz um bloco <strong>Bobina (FEM)</strong> para cada circuito da Malha: é a bobina do modelo de campo, com a indutância e o acoplamento calculados pelo FEM.</li><li>Na barra superior do esquemático, adicione <strong>fontes de tensão ou de corrente</strong>, <strong>resistores</strong>, <strong>indutores</strong>, <strong>capacitores</strong> e o <strong>Terra</strong> (obrigatório).</li><li>Clique num terminal e depois em outro para ligar um <strong>fio</strong>. Arraste os blocos para organizar e os trechos do fio para mudar o caminho.</li></ol><table tabindex="0"><thead><tr><th>Tecla</th><th>Ação</th></tr></thead><tbody><tr><td><code>W</code></td><td>modo fio</td></tr><tr><td><code>R</code></td><td>girar o componente</td></tr><tr><td><code>M</code></td><td>espelhar</td></tr><tr><td><code>Del</code></td><td>apagar</td></tr><tr><td>roda do mouse</td><td>zoom</td></tr></tbody></table><h2 id="fontes" tabindex="-1">Fontes <a class="header-anchor" href="#fontes" aria-label="Permalink to &quot;Fontes&quot;">​</a></h2><p>Uma fonte tem amplitude, frequência, fase e nível CC, ou uma <strong>expressão em t</strong> (em segundos) que usa as variáveis do projeto: <code>V0*sin(2*pi*60*t)</code>, <code>24</code> para CC, <code>24*min(1, t/0.001)</code> para uma rampa rápida (1 ms). As expressões usam <code>+ - * / ^</code>, <code>pi</code> e funções como <code>sin</code>, <code>cos</code>, <code>exp</code>, <code>sqrt</code>, <code>abs</code>, <code>min</code> e <code>max</code>.</p><h2 id="resolver-e-ver-os-sinais" tabindex="-1">Resolver e ver os sinais <a class="header-anchor" href="#resolver-e-ver-os-sinais" aria-label="Permalink to &quot;Resolver e ver os sinais&quot;">​</a></h2><p>Resolva a física de campo na análise <strong>transitória</strong>: as bobinas do esquemático recebem a corrente do circuito a cada passo. Depois de resolver, clique num componente para ver <strong>i(t)</strong> e <strong>v(t)</strong>; os sinais marcados aparecem embaixo do esquemático.</p><p>Exemplos típicos:</p><ul><li><strong>Circuito RL</strong>: fonte de tensão, resistor e a bobina. A corrente sobe com a constante de tempo L/R, com L vinda do FEM (e variando se o aço saturar).</li><li><strong>Transformador</strong>: fonte de tensão no primário e carga resistiva no secundário. Com acoplamento perfeito, V2 = (N2/N1)·V1.</li></ul><div class="tip custom-block"><p class="custom-block-title">Circuito por código</p><p>Para acoplar também o <strong>movimento</strong> (um êmbolo que se desloca com a força magnética), use a <a href="./../scripting/bridge.html">ponte local</a>: o exemplo do <a href="./../scripting/examples.html#contator">contator</a> integra circuito, campo e mecânica num laço em Python.</p></div>',12)])])}const g=e(i,[["render",s]]);export{p as __pageData,g as default};
